def get_config_value(config, key, default=None):
    """Get a value from a configuration dictionary.

    :param dict config: configuration dictionary
    :param str key: key to look up
    :param default: default value to return if key not found
    :returns: value from config
    """
    if key not in config:
        return default
    return config[key]


def get_config_value_or_raise(config, key):
    """Get a value from a configuration dictionary.

    :param dict config: configuration dictionary
    :param str key: key to look up
    :returns: value from config
    :raises: :class:`ValueError` if key not found
    """
    if key not in config:
        raise ValueError('key not found: %s' % key)
    return config[key]


